"""Isolated Chromium UI + simulated API; no Supabase / SQL execution."""
from pathlib import Path
from playwright.sync_api import sync_playwright
root=Path(__file__).resolve().parents[1]
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox']);page=b.new_page();page.set_default_timeout(5000);errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
 page.set_content('<div id="jtg_5"></div><div id="teacher"></div>')
 page.evaluate('''()=>{window.S={role:'direccion_escolar'};window.supabaseClient={auth:{getSession:async()=>({data:{session:{access_token:'mock'}}})}};window.jaguarReadJson=r=>r.json();window.toast=x=>window.msg=x;window.confirm=()=>true;window.prompt=()=>"Cancelación documentada de prueba";window.posts=[];window.group=null;window.recorded=false;window.fetch=async(url,opts={})=>{let data;if(opts.method==='POST'){const b=JSON.parse(opts.body);posts.push(b);if(b.action==='temporary_group'){if(b.operation==='activate')group={state:'activo',rosterCount:2,version:2,room:'4',reference:b.reference,sessions:[{id:'6',period:1,date:'2027-07-05',start:540,end:600,teacher:'3'}]};else group.state='cancelado';}else recorded=true;data={state:'ok'};}else if(url.includes('view=temporary_group'))data={group,ready:true,version:2,fingerprint:'a'.repeat(32),rooms:[{id:'4',code:'A4',name:'Aula 4',capacity:20}],experimental:true};else if(url.includes('session='))data={rows:[{student:'2',name:'Alumno ejemplo A',state:recorded?'presente':null},{student:'3',name:'Alumno ejemplo B',state:recorded?'falta':null}],recorded,canWrite:!recorded,experimental:true};else data={sessions:[{id:'6',name:'RC-MAT-001',period:1,date:'2027-07-05',start:540,end:600,room:'Aula 4',recorded}],experimental:true};return new Response(JSON.stringify({ok:true,data}),{headers:{'Content-Type':'application/json'}});};}''')
 page.add_script_tag(path=str(root/'assets/jaguar360-temporary-group.js'))
 page.evaluate("jaguarTemporaryGroup.group('5')");page.get_by_role('button',name='Activar grupo temporal de prueba').wait_for();page.locator('#jtg_room_5').select_option('4')
 for key in ['holders','contents','students','calendar','workload','room']:page.locator('#jtg_check_'+key+'_5').check()
 page.locator('#jtg_ref_5').fill('Acta 001');page.locator('#jtg_reason_5').fill('Revisión documental completa de prueba');page.get_by_role('button',name='Activar grupo temporal de prueba').click();page.get_by_text('Grupo temporal · activo').wait_for();assert page.evaluate('posts[0].checks.holders')
 page.get_by_role('button',name='Cancelar grupo antes de su inicio').click();page.get_by_text('Grupo temporal · cancelado').wait_for();assert page.evaluate('posts[1].operation')=='cancel'
 page.evaluate("S.role='docente';document.getElementById('teacher').innerHTML=jaguarTemporaryGroup.teacherHtml()")
 page.get_by_role('button',name='Consultar mis sesiones temporales').click();page.get_by_role('button',name='Abrir lista temporal').click();page.get_by_role('button',name='Confirmar lista temporal completa').click();assert page.evaluate('posts.length')==2;assert page.evaluate('msg')=='Completa todas las marcas.'
 page.locator('#jtg_mark_0').select_option('presente');page.locator('#jtg_mark_1').select_option('falta');page.get_by_role('button',name='Confirmar lista temporal completa').click();page.get_by_text('Lista confirmada.',exact=True).wait_for();assert page.evaluate('posts[2].marks[1].student')=='3';assert not errors,errors;print('OK: activación/cancelación; lista temporal completa y validación de campos (API simulada).');b.close()
